function geoPickerMarkup(p={}){return `<fieldset style="border:1px dashed var(--line);padding:12px"><legend>国家与城市标签（选填）</legend><label for="geoCountry">国家 / 地区</label><select id="geoCountry" aria-label="国家标签"></select><label for="geoCity">城市</label><select id="geoCity" aria-label="城市标签"></select><p class="hint">直接选择即可，★ 表示用过的标签。同名城市按州／省区分。内置主要城市目录；未收录的可暂不设置城市。${p.country||p.city?'已有记录：'+esc([p.country,p.city].filter(Boolean).join(' · ')):''}</p></fieldset>`}
function bindGeoPicker(p={}){let country=p.countryTag||'',city=p.cityTag||'';const cs=$('geoCountry'),ci=$('geoCity');const usedCountries=new Set(state.places.map(p=>p.countryTag)),usedCities=new Set(state.places.map(p=>p.cityTag));cs.innerHTML='<option value="">请选择国家 / 地区</option>'+[...GeoCountries].sort((a,b)=>Number(usedCountries.has(b.code))-Number(usedCountries.has(a.code))||a.name.localeCompare(b.name,'zh')).map(c=>`<option value="${c.code}" ${country===c.code?'selected':''}>${usedCountries.has(c.code)?'★ ':''}${esc(c.name)} · ${esc(c.en)}</option>`).join('');let choices=[];function cities(){const saved=(state.geoTags||[]).filter(t=>t.country===country);choices=[...new Map([...saved,...GeoCities.filter(t=>t.country===country)].map(t=>[t.id,t])).values()];if(p.cityTag&&p.countryTag===country&&!choices.some(t=>t.id===p.cityTag))choices.unshift({id:p.cityTag,country,name:p.city});choices.sort((a,b)=>Number(usedCities.has(b.id))-Number(usedCities.has(a.id))||a.name.localeCompare(b.name,'zh'));ci.innerHTML='<option value="">'+(country?'请选择城市（也可暂不设置）':'请先选择国家')+'</option>'+choices.map(t=>`<option value="${t.id}" ${city===t.id?'selected':''}>${usedCities.has(t.id)?'★ ':''}${esc(t.name)}${t.region?' · '+esc(t.region):''}</option>`).join('');ci.disabled=!country}cities();cs.onchange=()=>{country=cs.value;city='';cities()};ci.onchange=()=>city=ci.value;return ()=>{const c=GeoCountries.find(c=>c.code===cs.value),t=choices.find(t=>t.id===ci.value);return{countryTag:c?.code||'',cityTag:t?.id||'',country:c?.name||'',city:t?.name||''}}}
function batchGeoTags(ids,trip){show(`<h2>为选中记录设置国家与城市</h2><p class="hint">只更新这 ${ids.length} 条记录的国家、城市标签；同一旅程内只计一次。</p>${geoPickerMarkup()}<div class="actions"><button id="geoCancel">取消</button><button id="geoApply" class="primary">应用标签</button></div>`);const read=bindGeoPicker();$('geoCancel').onclick=()=>tripManager(trip);$('geoApply').onclick=async()=>{const tags=read();if(!tags.countryTag){toast('请先选择国家');return}try{await commit({...state,places:state.places.map(p=>ids.includes(p.id)?{...p,...tags}:p)});tripManager(trip);toast('国家与城市标签已更新')}catch(e){error(e)}}}

